/**
 * dsh-tiny-tool client settings UI.
 *
 * Registers a settings card in the DSH Settings page that lets users manage
 * `exemptTools` and `exemptPrefixes` exception lists.
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
(window as any).__ModuleLoader__?.load({
  id: 'dsh-tiny-tool',
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    factory: (require: any) => {
    const React = require('react')

    const NS = 'tiny-tool-config'

    // ─── helpers ────────────────────────────────────────────────────────────

    function getService(ctx: any, name: string): any {
      if (!ctx) return undefined
      if (typeof ctx.get === 'function') {
        try { return ctx.get(name) } catch { /* ignore */ }
      }
      const anyCtx = ctx as unknown as Record<string, unknown>
      return anyCtx[name]
    }

    function valueField(
      id: string,
      label: string,
      hint: string,
      value: string,
      onEdit: (v: string) => void,
    ): React.ReactElement {
      return React.createElement('div', { className: 'dtt-field' },
        React.createElement('div', { className: 'dtt-fieldHead' },
          React.createElement('label', { className: 'dtt-label', htmlFor: id }, label),
        ),
        React.createElement('input', {
          id,
          className: 'dtt-input',
          type: 'text',
          value: value ?? '',
          onChange: (e: any) => onEdit(e.currentTarget.value),
        }),
        hint ? React.createElement('span', { className: 'dtt-hint' }, hint) : null,
      )
    }

    function tagField(
      id: string,
      label: string,
      hint: string,
      tags: string[],
      onAdd: (tag: string) => void,
      onRemove: (tag: string) => void,
    ): React.ReactElement {
      return React.createElement('div', { className: 'dtt-field' },
        React.createElement('div', { className: 'dtt-fieldHead' },
          React.createElement('label', { className: 'dtt-label', htmlFor: id }, label),
        ),
        hint ? React.createElement('span', { className: 'dtt-hint' }, hint) : null,
        React.createElement('div', { className: 'dtt-tags' },
          tags.map((tag) =>
            React.createElement('span', {
              key: tag,
              className: 'dtt-tag',
              onClick: () => onRemove(tag),
            }, `× ${tag}`)),
          React.createElement('input', {
            className: 'dtt-tagInput',
            placeholder: 'add & press Enter',
            onKeyDown: (e: any) => {
              if (e.key === 'Enter' && e.currentTarget.value.trim()) {
                onAdd(e.currentTarget.value.trim())
                e.currentTarget.value = ''
              }
            },
          }),
        ),
      )
    }

    function boolField(
      id: string,
      label: string,
      hint: string,
      value: boolean,
      onChange: (v: boolean) => void,
    ): React.ReactElement {
      return React.createElement('div', { className: 'dtt-field' },
        React.createElement('div', { className: 'dtt-fieldHead' },
          React.createElement('label', { className: 'dtt-label', htmlFor: id }, label),
        ),
        React.createElement('input', {
          id,
          className: 'dtt-switch',
          type: 'checkbox',
          checked: value ?? false,
          onChange: (e: any) => onChange(e.currentTarget.checked),
        }),
        hint ? React.createElement('span', { className: 'dtt-hint' }, hint) : null,
      )
    }

    // ─── locale ──────────────────────────────────────────────────────────────

    interface LocaleDict {
      title: string
      description: string
      intro: string
      exemptTools: string
      exemptToolsHint: string
      exemptPrefixes: string
      exemptPrefixesHint: string
      emptyParameters: string
      emptyParametersHint: string
      save: string
      saving: string
      discard: string
      unsaved: string
      loading: string
      settingsUnavailable: string
      saveFailed: string
    }

    const en: LocaleDict = {
      title: 'Tiny Tool',
      description: 'Hide tool descriptions from the system prompt.',
      intro: 'Configure which tools and prefixes should keep their full descriptions visible.',
      exemptTools: 'Exempt Tools',
      exemptToolsHint: 'Exact tool names to keep fully visible.',
      exemptPrefixes: 'Exempt Prefixes',
      exemptPrefixesHint: 'Tool name prefixes to keep fully visible (e.g. mnemon_).',
      emptyParameters: 'Empty Tool Parameters',
      emptyParametersHint: 'When enabled, non-exempt tools are sent with empty parameters instead of a trimmed schema.',
      save: 'Save',
      saving: 'Saving…',
      discard: 'Discard',
      unsaved: 'Unsaved',
      loading: 'Loading…',
      settingsUnavailable: 'Settings unavailable (namespace not registered).',
      saveFailed: 'Save failed',
    }
    const zh: LocaleDict = {
      title: 'Tiny Tool',
      description: '隐藏系统提示中的工具描述。',
      intro: '配置哪些工具和前缀应保持完整描述可见。',
      exemptTools: '豁免工具',
      exemptToolsHint: '保持完全可见的确切工具名称。',
      exemptPrefixes: '豁免前缀',
      exemptPrefixesHint: '保持完全可见的工具名前缀（如 mnemon_）。',
      emptyParameters: '清空工具参数',
      emptyParametersHint: '启用后，非豁免工具将以空参数发送，而非精简后的参数 schema。',
      save: '保存',
      saving: '保存中…',
      discard: '取消',
      unsaved: '未保存',
      loading: '加载中…',
      settingsUnavailable: '设置不可用（命名空间未注册）。',
      saveFailed: '保存失败',
    }

    function useActiveLocale(ctx: any): string {
      const localeSvc = getService(ctx, 'locale')
      return React.useSyncExternalStore(
        React.useMemo(() => (cb: any) => {
          if (localeSvc && typeof localeSvc.subscribe === 'function') return localeSvc.subscribe(cb)
          return () => {}
        }, [localeSvc]),
        () => {
          if (localeSvc && typeof localeSvc.getSnapshot === 'function') {
            const snap = localeSvc.getSnapshot()
            const active = snap && (snap as Record<string, unknown>).active
            if (typeof active === 'string' && active) return active
          }
          return typeof navigator !== 'undefined' ? String(navigator.language || '').slice(0, 2) : 'en'
        },
        () => 'en',
      )
    }

    function makeT(locale: string | undefined): (key: string) => string {
      const dict = String(locale || '').startsWith('ru') ? zh : en
      return (key: string) => dict[key as keyof LocaleDict] || en[key as keyof LocaleDict] || key
    }

    // ─── settings form ────────────────────────────────────────────────────────

    interface ConfigState {
      exemptTools: string[]
      exemptPrefixes: string[]
      emptyParameters: boolean
    }

    function TinyToolSettingsForm({ t, ctx }: { t: (key: string) => string; ctx: any }) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const [draft, setDraft] = React.useState(null as any)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const [saved, setSaved] = React.useState(null as any)
      const [saving, setSaving] = React.useState(false)
      const [err, setErr] = React.useState('')

      // Native settings read: configForms.get(ns) → reactive { status, value, writable }
      const forms = getService(ctx, 'configForms')
      const scope = React.useMemo(
        () => (forms && typeof forms.get === 'function' ? forms.get(NS) : undefined),
        [forms],
      )

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const snapshot = React.useSyncExternalStore(
        React.useMemo(() => ((cb: any) => (scope ? scope.subscribe(cb) : () => {})), [scope]),
        React.useCallback(() => (scope ? scope.getSnapshot() : { status: 'unavailable' as const }), [scope]),
        React.useCallback(() => ({ status: 'loading' as const }), []),
      )

      const status = snapshot?.status || 'unavailable'
      const writable = snapshot?.writable !== undefined ? snapshot.writable : true

      // Sync draft/saved from the native scope value (no REST fetch needed)
      React.useEffect(() => {
        if (status === 'unavailable' || !snapshot?.value) return
        const value = snapshot.value as Record<string, unknown> | undefined
        setDraft({
          exemptTools: Array.isArray(value?.exemptTools) ? value.exemptTools : [],
          exemptPrefixes: Array.isArray(value?.exemptPrefixes) ? value.exemptPrefixes : [],
          emptyParameters: typeof value?.emptyParameters === 'boolean' ? value.emptyParameters : true,
        })
        setSaved({
          exemptTools: Array.isArray(value?.exemptTools) ? value.exemptTools : [],
          exemptPrefixes: Array.isArray(value?.exemptPrefixes) ? value.exemptPrefixes : [],
          emptyParameters: typeof value?.emptyParameters === 'boolean' ? value.emptyParameters : true,
        })
      }, [status, snapshot])

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const setField = (key: keyof ConfigState, value: string[] | boolean) => setDraft((d: any) => d ? { ...d, [key]: value } : { exemptTools: value as string[], exemptPrefixes: [] })
      const dirty = !!(draft && saved && (
        JSON.stringify(draft.exemptTools) !== JSON.stringify(saved.exemptTools) ||
        JSON.stringify(draft.exemptPrefixes) !== JSON.stringify(saved.exemptPrefixes) ||
        draft.emptyParameters !== saved.emptyParameters
      ))

      const blocked = !dirty || saving || !draft || !writable || status !== 'ready'

      const save = async () => {
        if (!draft || blocked) return
        setErr('')
        setSaving(true)
        try {
          const payload = { exemptTools: draft.exemptTools, exemptPrefixes: draft.exemptPrefixes, emptyParameters: draft.emptyParameters }
          // Native write via the settings service (direct update/replace)
          const sctx = getService(ctx, 'settings')
          const svc = sctx ? sctx.settings : undefined
          const revision = snapshot?.revision ?? undefined
          if (typeof svc?.update === 'function') {
            await svc.update(NS, structuredClone(payload), revision)
          } else if (typeof svc?.replace === 'function') {
            await svc.replace(NS, structuredClone(payload), revision)
          } else {
            throw new Error('native settings service unavailable')
          }
          setSaved({ exemptTools: payload.exemptTools, exemptPrefixes: payload.exemptPrefixes })
        } catch (e: unknown) {
          setErr(e instanceof Error ? e.message : String(e))
        } finally {
          setSaving(false)
        }
      }

      if (status === 'loading' || (!draft && !err && status !== 'unavailable')) {
        return React.createElement('p', { className: 'dtt-failed' }, t('loading'))
      }
      if (status === 'unavailable') {
        return React.createElement('p', { className: 'dtt-failed' }, t('settingsUnavailable'))
      }

      return React.createElement(React.Fragment, null,
        React.createElement('p', { className: 'dtt-hint' }, t('intro')),
        tagField('dtt-exempt-tools', t('exemptTools'), t('exemptToolsHint'),
          draft?.exemptTools ?? [],
          (tag) => setField('exemptTools', [...(draft?.exemptTools ?? []), tag]),
          (tag) => setField('exemptTools', (draft?.exemptTools ?? []).filter((x: string) => x !== tag)),
        ),
        tagField('dtt-exempt-prefixes', t('exemptPrefixes'), t('exemptPrefixesHint'),
          draft?.exemptPrefixes ?? [],
          (tag) => setField('exemptPrefixes', [...(draft?.exemptPrefixes ?? []), tag]),
          (tag) => setField('exemptPrefixes', (draft?.exemptPrefixes ?? []).filter((p: string) => p !== tag)),
        ),
        boolField('dtt-empty-params', t('emptyParameters'), t('emptyParametersHint'),
          draft?.emptyParameters ?? true,
          (v: boolean) => setField('emptyParameters', v),
        ),
        React.createElement('div', { className: 'dtt-foot' },
          err ? React.createElement('p', { className: 'dtt-failed' }, err || t('saveFailed')) : null,
          React.createElement('button', {
            type: 'button',
            className: 'dtt-discard',
            disabled: !dirty || saving,
            onClick: () => { setDraft(saved); setErr('') },
          }, t('discard')),
          React.createElement('button', {
            type: 'button',
            className: 'dtt-save',
            disabled: blocked,
            onClick: save,
          }, t(saving ? 'saving' : 'save')),
        ),
      )
    }

    // ─── card wrapper ────────────────────────────────────────────────────────

    function TinyToolCard({ t, open, onOpen, children }: {
      t: (key: string) => string
      open: boolean
      onOpen: React.Dispatch<React.SetStateAction<boolean>>
      children: React.ReactNode
    }) {
      return React.createElement('li', { className: 'dtt-card' + (open ? ' dtt-cardOpen' : '') },
        React.createElement('button', {
          type: 'button',
          className: 'dtt-head',
          'aria-expanded': open,
          'aria-label': (open ? t('collapse') : t('expand')) + ': ' + t('title'),
          onClick: () => onOpen((v: boolean) => !v),
        },
          React.createElement('span', { className: 'dtt-headText' },
            React.createElement('span', { className: 'dtt-title' }, t('title')),
            React.createElement('span', { className: 'dtt-sub' }, t('description')),
          ),
          React.createElement('span', { className: 'dtt-chevron' + (open ? ' dtt-chevronOpen' : '') }, '▾'),
        ),
        React.createElement('div', {
          className: 'dtt-body',
          hidden: !open,
          style: open ? undefined : { display: 'none' },
        }, children),
      )
    }

    // ─── root component ──────────────────────────────────────────────────────

    function TinyToolPluginCard({ ctx }: { ctx: any }) {
      const [open, setOpen] = React.useState(false)
      const locale = useActiveLocale(ctx)
      const t = makeT(locale)
      return React.createElement(TinyToolCard, { t, open, onOpen: setOpen },
        React.createElement(TinyToolSettingsForm, { t, ctx }),
      )
    }

    // ─── apply ────────────────────────────────────────────────────────────────

    function apply(ctx: any): void {
      const slotsSvc = getService(ctx, 'slots')
      if (slotsSvc && typeof slotsSvc.inject === 'function') {
        try {
          slotsSvc.inject('settings.plugin.item', () => slotsSvc.register(
            {
              name: 'settings.plugin.item',
              key: NS,
              locale: NS,
              inject: () => ({ ctx }),
            },
            (props: Record<string, unknown>) => React.createElement(TinyToolPluginCard, Object.assign({}, props, { ctx })),
          ))
        } catch (err: unknown) {
          console.error('[dsh-tiny-tool] settings registration error:', err)
        }

        // Mount on the DSH Plugins page. The new web GUI renders plugin
        // setting cards in the `plugins.item` slot; the harness Settings UI
        // does not render `settings.plugin.item`, so without this the card
        // was effectively invisible there. Mirrors dsh-gitea, which keeps
        // both seats.
        try {
          slotsSvc.inject('plugins.item', () => slotsSvc.register(
            {
              name: 'plugins.item',
              id: NS,
              order: 60,
              label: () => 'dsh-tiny-tool',
              inject: () => ({ ctx }),
            },
            (props: Record<string, unknown>) => React.createElement(TinyToolPluginCard, Object.assign({}, props, { ctx })),
          ))
        } catch (err: unknown) {
          console.error('[dsh-tiny-tool] plugins.item registration error:', err)
        }
      }
    }

    // NOTE (0.2.0): legacy scoped settings + REST removed.
    // The card now reads via the native configForms.get(ns) snapshot and writes
    // directly to the native settings service (update/replace). Neither a scoped
    // `settingsScope` nor `/dsh-tiny-tool/config` fetch remains.
    // NOTE (0.2.1): return the plugin object directly instead of assigning to
    // `module.exports`. The client runtime loads this entry as an ES module
    // (`"type": "module"`), where the CommonJS global `module` is undefined and
    // surfaced as "import failed: module is not defined". dsh's ModuleLoader
    // invokes factory() and reads its return value, so a direct return is
    // equivalent to the proven gitea/pilot/context bundles (which instead
    // declare a local `var module = { exports: {} }` shim inside the factory).
    return { apply, inject: ['slots', 'locale', 'configForms'] }
  },
})
